<template><view class="page"><HmSkeleton v-if="loading" :rows="8"/><HmError v-else-if="error" :text="error" @retry="loadOrders"/><template v-else><view v-for="item in orders" :key="item.id" class="card"><view class="row"><text class="no hm-mono">{{item.orderNo}}</text><text :class="['status',statusClass(item.orderStatus)]">{{statusText(item.orderStatus)}}</text></view><view class="row"><text class="phone hm-mono">{{item.phone}}</text><text class="price hm-mono">¥{{item.cnyPrice}}</text></view><view class="row minor"><text>{{item.topupType==='BUNDLE'?'流量套餐':'话费充值'}}</text><text>{{formatDate(item.createdAt)}}</text></view></view><HmEmpty v-if="!orders.length" text="暂无充值记录"/></template></view></template>
<script setup>import{ref,onMounted}from'vue';import{orderApi}from'@/api';import HmSkeleton from'@/components/HmSkeleton.vue';import HmError from'@/components/HmError.vue';import HmEmpty from'@/components/HmEmpty.vue';const orders=ref([]),loading=ref(true),error=ref('');async function loadOrders(){loading.value=true;error.value='';try{const r=await orderApi.getMyOrders({page:1,size:50});orders.value=r.data?.records||[]}catch(e){error.value=e.message||'订单加载失败'}finally{loading.value=false}}function statusText(s){return{SUCCESS:'充值成功',SUCCESSFUL:'充值成功',CHARGING:'充值中',PENDING_PAY:'待支付',FAILED:'充值异常',REFUNDED:'已退款'}[s]||s}function statusClass(s){return(s==='SUCCESS'||s==='SUCCESSFUL')?'success':s==='FAILED'?'failed':'pending'}function formatDate(v){return v?String(v).replace('T',' ').slice(0,16):''}onMounted(loadOrders)</script>
<style scoped>.page{min-height:100vh;background:#F5F7FA;padding:24rpx}.card{background:#fff;border-radius:14rpx;padding:24rpx;margin-bottom:16rpx}.row{display:flex;justify-content:space-between;align-items:center;margin-bottom:14rpx}.row:last-child{margin:0}.no{font-size:23rpx;color:#999}.status{font-size:24rpx}.success{color:#52C41A}.failed{color:#FF4D4F}.pending{color:#1890FF}.phone{font-size:30rpx}.price{font-size:34rpx;font-weight:700;color:#003366}.minor{font-size:24rpx;color:#999}</style>